    19	    endpoint = data.endpoint ?? endpoint;
    20	    let result: unknown;
    21	    if (data.type === 'load') {
    22	      endpoint = data.endpoint!;
    23	      const state = await readState();
    24	      const workspace = recordsWorkspace(state.records);
    25	      result = { state, workspace: workspace ? deserializeWorkspace(workspace, 'current') : null };
    26	    } else if (data.type === 'project') {
    27	      // A restarted worker can retry in-flight writes immediately, but must know
    28	      // the complete key set before diffing an explicit workspace replacement.
    29	      if (!initialized) await readState();
    30	      const records = workspaceRecords(deserializeWorkspace(data.snapshot));
    31	      result = [...Object.entries(records).filter(([key, value]) => JSON.stringify(value) !== known.get(key)).map(([key, value]) => ({ key, value })),
    32	        ...[...known.keys()].filter(key => !Object.hasOwn(records, key)).map(key => ({ key, delete: true }))];
    33	    } else {
    34	      const batch = data.batch!;
    35	      let body = bodies.get(batch.requestId);
    36	      if (!body) {
    37	        body = JSON.stringify({ ...batch, changes: batch.changes.map(c => 'value' in c ? { ...c, value: normalizeRecord(c.key, c.value) } : c) });
    38	        bodies.set(batch.requestId, body);
    39	      }
    40	      const response = await fetch(endpoint, { method: 'POST', headers: { 'content-type': 'application/json' }, body });
    41	      result = await response.json();
    42	      if (!response.ok) {
    43	        // A server/transport failure can happen after publication. Only a client
    44	        // rejection proves the transaction was not accepted.
    45	        const rejected = response.status >= 400 && response.status < 500;
    46	        if (rejected) bodies.delete(batch.requestId);
    47	        throw Error((rejected ? 'REJECTED: ' : 'Write uncertain: ') + ((result as { error?: string }).error ?? 'Could not save storage'));
    48	      }
