    18	  try {
    19	    endpoint = data.endpoint ?? endpoint;
    20	    let result: unknown;
    21	    if (data.type === 'load') {
    22	      endpoint = data.endpoint!;
    23	      const state = await readState();
    24	      const workspace = recordsWorkspace(state.records);
    25	      result = { state, workspace: workspace ? deserializeWorkspace(workspace, 'current') : null };
    26	    } else if (data.type === 'project') {
    27	      // A restarted worker can retry in-flight writes immediately, but must know
    28	      // the complete key set before diffing an explicit workspace replacement.
    29	      if (!initialized) await readState();
    30	      const records = workspaceRecords(deserializeWorkspace(data.snapshot));
    31	      result = [...Object.entries(records).filter(([key, value]) => JSON.stringify(value) !== known.get(key)).map(([key, value]) => ({ key, value })),
