    33	    } else {
    34	      const batch = data.batch!;
    35	      let body = bodies.get(batch.requestId);
    36	      if (!body) {
    37	        body = JSON.stringify({ ...batch, changes: batch.changes.map(c => 'value' in c ? { ...c, value: normalizeRecord(c.key, c.value) } : c) });
    38	        bodies.set(batch.requestId, body);
    39	      }
    40	      const response = await fetch(endpoint, { method: 'POST', headers: { 'content-type': 'application/json' }, body });
    41	      result = await response.json();
    42	      if (!response.ok) {
    43	        // A server/transport failure can happen after publication. Only a client
    44	        // rejection proves the transaction was not accepted.
    45	        const rejected = response.status >= 400 && response.status < 500;
    46	        if (rejected) bodies.delete(batch.requestId);
