    31	    const request = async (path: string, body?: unknown, method = body === undefined ? 'GET' : 'POST') => {
    32	      const response = await apiFetch(`/api/mapping/agent${path}`, { method, signal: abort.signal,
    33	        ...(body === undefined ? {} : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }) });
    34	      if (!response.ok) throw await errorFrom(response);
    35	      return response.json();
    36	    };
