    38	    const run = async () => {
    39	      try {
    40	        await register();
    41	        while (!abort.signal.aborted) {
    42	          const commands: CanvasCommand[] = await request(`/canvases/${canvasId}/commands`);
    43	          for (const command of commands) {
    44	            const started = performance.now();
    45	            let result = results.get(command.id);
    46	            if (!result) {
    47	              try { result = { value: await latest.current.handle(command) }; }
    48	              catch (error) { result = { error: error instanceof Error ? error.message : String(error) }; }
    49	              if (mutationCommands.has(command.method)) results.set(command.id, result);
    50	              if (results.size > 200) results.delete(results.keys().next().value!);
    51	            }
    52	            const handled = performance.now();
    53	            const reply = canvasReply(command, result);
    54	            const encoded = performance.now();
    55	            const response = await apiFetch(`/api/mapping/agent/canvases/${canvasId}/reply`, { method: 'POST', signal: abort.signal,
    56	              headers: { 'content-type': 'application/json', 'x-canvas-command-id': command.id }, body: reply.body });
