    59	              await request(`/canvases/${canvasId}/reply`, { commandId: command.id,
    60	                error: `CANVAS_REPLY_REJECTED: method=${command.method} actualBytes=${reply.bytes} status=${response.status}; retry the identical requestId if this was a mutation` });
    61	            }
