    63	          }
    64	          await register();
    65	        }
    66	      } catch {
    67	        if (!abort.signal.aborted) timer = setTimeout(() => void run(), 1000);
    68	      }
    69	    };
    70	    void run();
    71	    const unregister = () => { void apiFetch(`/api/mapping/agent/canvases/${canvasId}`, { method: 'DELETE', keepalive: true }).catch(() => undefined); };
