    73	    // promptly, without ever deleting a replacement that has the same stable ID.
    74	    window.addEventListener('pagehide', unregister);
    75	    return () => { abort.abort(); clearTimeout(timer); window.removeEventListener('pagehide', unregister); unregister(); };
    76	  }, [canvasId, identity]);
    77	  useEffect(() => {
    78	    setAgentStatus({ connected: false, count: 0 });
    79	    if (!workspace || !identity) return;
    80	    const endpoint = new URL(`${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/mapping/live`, location.href);
